use std::io

fn height(l: Vec<int>, r: Vec<int>, n: int) -> int {
    if n < 0 {
        return 0
    }
    let a = height(l, r, l[n as usize])
    let b = height(l, r, r[n as usize])
    if a > b { a + 1 } else { b + 1 }
}

fn main() {
    let mut keys: Vec<int> = []
    let mut lc: Vec<int> = []
    let mut rc: Vec<int> = []
    let mut root: int = -1
    loop {
        let line = io::read_line() ?? ""
        if line == "" {
            break
        }
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "inorder" {
            let mut out = ""
            let mut stack: Vec<int> = []
            let mut cur = root
            while cur >= 0 || stack.len() > 0 {
                while cur >= 0 {
                    stack.push(cur)
                    cur = lc[cur as usize]
                }
                let top = stack.pop() ?? 0
                if out != "" { out = out + " " }
                out = out + "${keys[top as usize]}"
                cur = rc[top as usize]
            }
            if out == "" { println("<empty>") } else { println(out) }
        } else if cmd == "height" {
            println("${height(lc, rc, root)}")
        } else if cmd == "min" || cmd == "max" {
            if root < 0 {
                println("empty")
            } else {
                let mut c = root
                if cmd == "min" {
                    while lc[c as usize] >= 0 { c = lc[c as usize] }
                } else {
                    while rc[c as usize] >= 0 { c = rc[c as usize] }
                }
                println("${keys[c as usize]}")
            }
        } else {
            let x: int = parts[1].parse::<int>() ?? 0
            if cmd == "insert" {
                if root < 0 {
                    keys.push(x)
                    lc.push(-1)
                    rc.push(-1)
                    root = 0
                    println("ok")
                } else {
                    let mut c = root
                    let mut done = false
                    while !done {
                        let k = keys[c as usize]
                        if x == k {
                            println("dup")
                            done = true
                        } else if x < k {
                            if lc[c as usize] < 0 {
                                keys.push(x)
                                lc.push(-1)
                                rc.push(-1)
                                lc[c as usize] = keys.len() as int - 1
                                println("ok")
                                done = true
                            } else {
                                c = lc[c as usize]
                            }
                        } else {
                            if rc[c as usize] < 0 {
                                keys.push(x)
                                lc.push(-1)
                                rc.push(-1)
                                rc[c as usize] = keys.len() as int - 1
                                println("ok")
                                done = true
                            } else {
                                c = rc[c as usize]
                            }
                        }
                    }
                }
            } else if cmd == "contains" {
                let mut c = root
                let mut found = false
                while c >= 0 && !found {
                    let k = keys[c as usize]
                    if x == k {
                        found = true
                    } else if x < k {
                        c = lc[c as usize]
                    } else {
                        c = rc[c as usize]
                    }
                }
                if found { println("yes") } else { println("no") }
            } else if cmd == "delete" {
                let mut parent: int = -1
                let mut c = root
                while c >= 0 && keys[c as usize] != x {
                    parent = c
                    if x < keys[c as usize] { c = lc[c as usize] } else { c = rc[c as usize] }
                }
                if c < 0 {
                    println("missing")
                } else {
                    let mut repl: int = -1
                    if lc[c as usize] < 0 {
                        repl = rc[c as usize]
                    } else if rc[c as usize] < 0 {
                        repl = lc[c as usize]
                    } else {
                        // in-order successor
                        let mut sp = c
                        let mut s = rc[c as usize]
                        while lc[s as usize] >= 0 {
                            sp = s
                            s = lc[s as usize]
                        }
                        if sp != c {
                            lc[sp as usize] = rc[s as usize]
                            rc[s as usize] = rc[c as usize]
                        }
                        lc[s as usize] = lc[c as usize]
                        repl = s
                    }
                    if parent < 0 {
                        root = repl
                    } else if lc[parent as usize] == c {
                        lc[parent as usize] = repl
                    } else {
                        rc[parent as usize] = repl
                    }
                    println("ok")
                }
            }
        }
    }
}

